pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address ref, uint256 wait) public {
        vm.assume(actor != address(0));
        vm.assume(ref != address(0));
        // keep wait admissible: at least one full production cycle, within a wide window
        wait = bound(wait, 86400, 86400 * 1000);

        // initialize the market (seed with some drugs)
        address seeder = address(0x1234);
        vm.deal(seeder, 1 ether);
        vm.prank(seeder);
        c.seedMarket{value: 0}(1000);

        // caller claims the free starting kilos (300) -> lastCollect set to now
        vm.prank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);

        // advance time; production is capped at DRUGS_TO_PRODUCE_1KILO seconds
        vm.warp(block.timestamp + wait);

        vm.prank(actor);
        c.collectDrugs(ref);

        uint256 kilosAfter = c.Kilos(actor);

        // Rule: exactly one kilo is produced per capped full cycle (86400s at 300 kilos = 86400 drugs)
        // since wait >= 86400, production is capped and collectDrugs must add exactly ONE kilo.
        assertTrue(kilosAfter - kilosBefore == 1);
    }
}

