pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address ref) public {
        vm.assume(actor != address(0));
        // fresh caller: no kilos, no claimed drugs, no referral yet
        vm.assume(c.Kilos(actor) == 0);
        vm.assume(c.claimedDrugs(actor) == 0);
        vm.assume(c.referrals(actor) == address(0));

        // initialize the market
        c.seedMarket(1);

        // caller takes the free starting kilos at time T0
        vm.warp(86400);
        vm.prank(actor);
        c.getFreeKilo();

        // exactly one production day passes, then one collectDrugs call
        vm.warp(86400 + 86400);
        vm.prank(actor);
        c.collectDrugs(ref);

        // P: one day of production adds exactly STARTING_KILOS kilos once -> 600
        // M: doubled increment -> 900
        assertTrue(c.Kilos(actor) == 2 * c.STARTING_KILOS());
    }
}

