        vm.assume(actor != address(0));
        warpDelta = bound(warpDelta, 1, 86400);

        c.seedMarket(1000);

        vm.prank(actor);
        c.getFreeKilo();

        // accrue some pending drugs
        vm.warp(block.timestamp + warpDelta);

        vm.prank(actor);
        c.collectDrugs(ref);
        uint256 kilosAfterFirst = c.Kilos(actor);

        // second collect at the SAME timestamp: no new drugs produced,
        // so Kilos must not change
        vm.prank(actor);
        c.collectDrugs(ref);
        uint256 kilosAfterSecond = c.Kilos(actor);

        assertTrue(kilosAfterSecond == kilosAfterFirst, "re-collect at same timestamp must not add Kilos");
    }
}
